import { readFile, writeFile } from "node:fs/promises";
const tokens = JSON.parse(await readFile("src/styles/tokens.json", "utf8"));
const marker =
  "/* Untold product UI scale — generated by scripts/sync-ui-tokens.mjs. */";
const path = "src/styles/tokens.css";
const existing = (await readFile(path, "utf8")).split(marker)[0].trimEnd();
const lines = tokens.spacing.map((value) => `  --space-${value}: ${value}px;`);
for (const [name, token] of Object.entries(tokens.typography))
  lines.push(`  --type-${name}: ${token.size}px;`);
lines.push(
  `  --shape-control: ${tokens.radius[tokens.component.button.radius]}px;`,
  `  --shape-card: ${tokens.radius[tokens.component.card.radius]}px;`,
  `  --control-height: ${tokens.component.button.height}px;`,
  `  --motion-normal: ${tokens.motion.normal}ms;`,
);
await writeFile(
  path,
  `${existing}\n\n${marker}\n:root {\n${lines.join("\n")}\n}\n`,
);
